package io.github.deepseekbridge;
import android.app.Application;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.accessibility.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;import java.io.*;import java.time.Duration;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class AppControlServiceTest {
 private AppControlService service;private AccessibilityNodeInfo root,input,button;private int sequence;
 @Before public void before(){service=Robolectric.buildService(AppControlService.class).create().get();service.onServiceConnected();service.getSharedPreferences("studio-app-control",0).edit().putStringSet("allowed",new HashSet<>(Arrays.asList("fixture.notes"))).commit();root=node("screen","android.widget.FrameLayout");input=node("original","android.widget.EditText");input.setEditable(true);input.setViewIdResourceName("fixture.notes:id/input");button=node("保存","android.widget.Button");button.setClickable(true);Shadows.shadowOf(root).addChild(input);Shadows.shadowOf(root).addChild(button);Shadows.shadowOf(service).setRootInActiveWindow(root);}
 @After public void after(){service.onDestroy();}
 private AccessibilityNodeInfo node(String text,String cls){AccessibilityNodeInfo n=AccessibilityNodeInfo.obtain();n.setPackageName("fixture.notes");n.setClassName(cls);n.setText(text);n.setVisibleToUser(true);n.setEnabled(true);n.setBoundsInScreen(new Rect(0,0,200,100));return n;}
 private JSONObject run(JSONObject args)throws Exception{AtomicReference<JSONObject> result=new AtomicReference<>();service.perform("app-fixture-"+(++sequence),args,result::set);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(500));assertNotNull(result.get());return result.get();}
 private void arm(){ReflectionHelpers.setField(service,"armed",true);}
 @Test public void serviceConnectsPausedAndCannotGrantItsOwnAccess()throws Exception{assertTrue(AppControlService.status(service).getBoolean("connected"));assertFalse(AppControlService.status(service).getBoolean("armed"));try{run(new JSONObject().put("action","observe"));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("暂停"));}assertFalse(AppControlService.status(service).getBoolean("armed"));}
 @Test public void observationReturnsActualRefsAndHidesPasswordText()throws Exception{arm();input.setPassword(true);JSONObject r=run(new JSONObject().put("action","observe"));assertEquals("fixture.notes",r.getString("package"));JSONArray nodes=r.getJSONArray("nodes");assertEquals(3,nodes.length());assertEquals("[密码已隐藏]",nodes.getJSONObject(1).getString("text"));assertFalse(r.toString().contains("original"));assertTrue(nodes.getJSONObject(2).getString("ref").startsWith("node-"));assertTrue(r.has("viewport"));}
 @Test public void observedRefActuallySetsTextAndClickDispatchesToTheNode()throws Exception{arm();JSONObject observed=run(new JSONObject().put("action","observe"));Shadows.shadowOf(input).setOnPerformActionListener((action,args)->{if(action==AccessibilityNodeInfo.ACTION_SET_TEXT)input.setText(args.getCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE));return true;});String ref=observed.getJSONArray("nodes").getJSONObject(1).getString("ref");assertTrue(run(new JSONObject().put("action","type").put("ref",ref).put("text","新输入")).getBoolean("actionAccepted"));assertEquals("新输入",input.getText().toString());AtomicInteger clicks=new AtomicInteger();Shadows.shadowOf(button).setOnPerformActionListener((action,args)->{if(action==AccessibilityNodeInfo.ACTION_CLICK)clicks.incrementAndGet();return true;});assertTrue(run(new JSONObject().put("action","click").put("target","保存")).getBoolean("actionAccepted"));assertEquals(1,clicks.get());}
 @Test public void changedTargetAndAmbiguousLabelsCannotBeClicked()throws Exception{arm();JSONObject observed=run(new JSONObject().put("action","observe"));String ref=observed.getJSONArray("nodes").getJSONObject(2).getString("ref");button.setText("删除");try{run(new JSONObject().put("action","click").put("ref",ref));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("改变"));}AccessibilityNodeInfo duplicate=node("删除","android.widget.Button");Shadows.shadowOf(root).addChild(duplicate);try{run(new JSONObject().put("action","click").put("target","删除"));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("不唯一"));}}
 @Test public void cancellationBeforeMainQueueAndUnapprovedPackagesPreventEffects()throws Exception{arm();AppControlService.cancel("cancel-before-main");try{service.perform("cancel-before-main",new JSONObject().put("action","observe"),r->fail());fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("取消"));}root.setPackageName("unapproved.app");try{run(new JSONObject().put("action","observe"));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("许可"));}assertTrue(AppControlService.protectedPackage(service,"com.android.permissioncontroller"));assertTrue(AppControlService.protectedPackage(service,service.getPackageName()));}
 @Test public void rawCoordinatesNeedAnObservationAndPausePreventsFurtherActions()throws Exception{arm();try{run(new JSONObject().put("action","click").put("x",1).put("y",1));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("过期"));}service.pause();try{run(new JSONObject().put("action","click").put("target","保存"));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("暂停"));}}
 @Test public void screenshotCannotBeDeliveredAfterWindowOrPauseChanges()throws Exception{arm();JSONObject observed=run(new JSONObject().put("action","observe"));int ticket=ReflectionHelpers.getField(service,"generation"),epoch=ReflectionHelpers.getField(service,"scrollEpoch");java.lang.reflect.Method verify=AppControlService.class.getDeclaredMethod("verifyCapture",int.class,JSONObject.class,int.class);verify.setAccessible(true);verify.invoke(service,ticket,observed,epoch);root.setPackageName("other.app");try{verify.invoke(service,ticket,observed,epoch);fail();}catch(java.lang.reflect.InvocationTargetException expected){assertTrue(expected.getCause() instanceof IOException);}root.setPackageName("fixture.notes");service.pause();try{verify.invoke(service,ticket,observed,epoch);fail();}catch(java.lang.reflect.InvocationTargetException expected){assertTrue(expected.getCause().getMessage().contains("暂停"));}}
}
